1	/**
2	 * Convert a string into a lowercase, dash-separated URL slug.
3	 * @param {string} str
4	 * @returns {string}
5	 */
6	export function slugify(str) {
7	  return String(str)
8	    .toLowerCase()
9	    .trim()
10	    .replace(/[^\p{L}\p{N}]+/gu, '-')
11	    .replace(/^-+|-+$/g, '');
12	}
13

1	import { describe, it, expect } from 'vitest';
2	import { slugify } from '../src/index.js';
3	
4	describe('slugify', () => {
5	  it('lowercases and dashes words', () => {
6	    expect(slugify('Hello World')).toBe('hello-world');
7	  });
8	
9	  it('collapses punctuation and whitespace', () => {
10	    expect(slugify('  Rock & Roll!!  ')).toBe('rock-roll');
11	  });
12	
13	  it('keeps digits', () => {
14	    expect(slugify('Top 10 Tips')).toBe('top-10-tips');
15	  });
16	});
